const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const portPoint = ee.Geometry.Point([-62.265, -38.79]); // Ingeniero White, Argentina (approx)
    const bufferKm = 10;
    const roiBuffer = portPoint.buffer(bufferKm * 1000);
    const argentina = ee.FeatureCollection('FAO/GAUL/2015/level0')
      .filter(ee.Filter.eq('ADM0_NAME', 'Argentina'))
      .geometry();
    const roi = roiBuffer.intersection(argentina, 1);

    const date1 = ee.Date('2025-01-30');
    const date2 = ee.Date('2025-03-11');

    const scale = 1000; // per best practice to avoid timeout
    const maxPixels = 1e10;

    // Helper: build S1 collection within window days
    function s1CollectionForDate(d, windowDays) {
      const start = d.advance(-windowDays, 'day');
      const end = d.advance(windowDays + 1, 'day'); // inclusive
      return ee.ImageCollection('COPERNICUS/S1_GRD')
        .filterBounds(roi)
        .filterDate(start, end)
        .filter(ee.Filter.eq('instrumentMode', 'IW'))
        .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
        .filter(ee.Filter.eq('resolution_meters', 10))
        .select(['VV']);
    }

    // Helper: compute water area stats for a date
    async function getWaterStats(date, label) {
      const windows = [3, 7, 14]; // progressive search
      let usedWindow = null;
      let col = null;
      for (let i = 0; i < windows.length; i++) {
        const w = windows[i];
        const candidate = s1CollectionForDate(date, w);
        const n = await candidate.size().getInfo();
        if (n > 0) {
          col = candidate;
          usedWindow = w;
          break;
        }
      }
      if (!col) {
        return { empty: true, label };
      }
      const imgCount = await col.size().getInfo();

      // Mosaic and convert to dB
      const mosaic = ee.Image(col.median());
      const vv = mosaic.select('VV');
      const vvDb = vv.updateMask(vv.gt(0)).log10().multiply(10); // dB

      // Water classification: VV_dB < -17 (typical open-water threshold)
      const water = vvDb.lt(-17).selfMask();

      // Valid area (any unmasked VV pixel)
      const validAreaImg = ee.Image.pixelArea().updateMask(vvDb.mask());
      const waterAreaImg = ee.Image.pixelArea().updateMask(water);

      const validArea = await validAreaImg.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: roi,
        scale: scale,
        maxPixels: maxPixels,
        tileScale: 2
      }).get('area').getInfo();

      const waterArea = await waterAreaImg.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: roi,
        scale: scale,
        maxPixels: maxPixels,
        tileScale: 2
      }).get('area').getInfo();

      // Additional validation: count of samples
      const validCount = await vvDb.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: scale,
        maxPixels: maxPixels,
        tileScale: 2
      }).get('VV').getInfo();

      return {
        label,
        usedWindow,
        imgCount,
        validArea_m2: validArea,
        waterArea_m2: waterArea,
        validCount
      };
    }

    // 2. Data Acquisition & Check
    const stats1 = await getWaterStats(date1, '2025-01-30');
    const stats2 = await getWaterStats(date2, '2025-03-11');

    if (stats1.empty || stats2.empty) {
      if (stats1.empty) console.log('Jan30 Images: 0');
      if (stats2.empty) console.log('Mar11 Images: 0');
      console.log('C1');
      return;
    }

    console.log(`Jan30 Window(d): ${stats1.usedWindow}, Images: ${stats1.imgCount}`);
    console.log(`Mar11 Window(d): ${stats2.usedWindow}, Images: ${stats2.imgCount}`);

    // 3. Processing Validation (C2 / C3 checks)
    function isInvalidNumber(x) {
      return x === null || x === undefined || (typeof x === 'number' && !isFinite(x));
    }

    if (isInvalidNumber(stats1.validArea_m2) || isInvalidNumber(stats2.validArea_m2) ||
        isInvalidNumber(stats1.waterArea_m2) || isInvalidNumber(stats2.waterArea_m2)) {
      console.log('C3');
      return;
    }

    const validKm2_1 = (stats1.validArea_m2 || 0) / 1e6;
    const validKm2_2 = (stats2.validArea_m2 || 0) / 1e6;
    const waterKm2_1 = (stats1.waterArea_m2 || 0) / 1e6;
    const waterKm2_2 = (stats2.waterArea_m2 || 0) / 1e6;

    if ((stats1.imgCount > 0 && (stats1.validCount === 0 || validKm2_1 === 0)) ||
        (stats2.imgCount > 0 && (stats2.validCount === 0 || validKm2_2 === 0))) {
      console.log('No valid pixels after masking.');
      console.log('C2');
      return;
    }

    // 4. Calculation
    const dWater = waterKm2_2 - waterKm2_1;

    // 5. Print concise evidence
    console.log(`Jan30 Valid km2: ${validKm2_1.toFixed(2)}, Water km2: ${waterKm2_1.toFixed(2)}`);
    console.log(`Mar11 Valid km2: ${validKm2_2.toFixed(2)}, Water km2: ${waterKm2_2.toFixed(2)}`);
    console.log(`Δ Water km2 (Mar11 - Jan30): ${dWater.toFixed(2)}`);

    // 6. Final Answer
    if (isNaN(dWater)) {
      console.log('C3');
    } else if (dWater > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
